const response = $input.item.json.response;

// Extraer componentes del mensaje
const lines = response.split('\n');
const firstLine = lines[0];

// Extraer tipo, alcance y descripción
const match = firstLine.match(/^(\w+)(\(([^)]+)\))?:\s*(.+)$/);

let type = 'feat';
let scope = '';
let description = firstLine;

if (match) {
  type = match[1];
  scope = match[3] || '';
  description = match[4];
}

// Extraer cuerpo del mensaje
const bodyStart = lines.findIndex(line => line.trim() === '') + 1;
const body = bodyStart > 0 ? lines.slice(bodyStart).join('\n').trim() : '';

// Detectar breaking changes
const hasBreakingChanges = response.toLowerCase().includes('breaking change');

return {
  json: {
    commitMessage: response,
    type: type,
    scope: scope,
    description: description,
    body: body,
    hasBreakingChanges: hasBreakingChanges,
    timestamp: new Date().toISOString()
  }
};
